from PIL import Image
import numpy as np
m=np.array(Image.open('/app/target.png').convert('L'))<100
for x,y,dx,dy in [(350,430,64,-11),(414,415,64,-15),(375,298,-80,43),(645,433,90,-20)]:
 n=np.array([-dy,dx],float); n/=np.linalg.norm(n); ss=[]
 for s in np.arange(-80,81,.5):
  xx=int(round(x+s*n[0])); yy=int(round(y+s*n[1]));
  if m[yy,xx]:ss.append(s)
 # runs
 runs=[]
 if ss:
  a=b=ss[0]
  for z in ss[1:]:
   if z>b+.51:runs.append((a,b));a=z
   b=z
  runs.append((a,b))
 print((x,y),n,'runs',runs)
